   424	  env: NodeJS.ProcessEnv,
   425	): string | undefined {
   426	  const rawFd = env.LATTICE_MANAGED_HOST_WORKER_CAPABILITY_FD?.trim();
   427	  if (!rawFd) return undefined;
   428	  const fd = Number(rawFd);
   429	  if (!Number.isInteger(fd) || fd < 3 || fd > 255) {
   430	    throw new Error('managed host run worker: proposal capability fd must be between 3 and 255');
