   434	    throw new Error('managed host run worker: proposal capability must arrive over a non-file descriptor');
   435	  }
   436	  const key = readFileSync(fd, 'utf8').trim();
   437	  if (!/^[A-Za-z0-9+/]{43}=$/.test(key)) {
   438	    throw new Error('managed host run worker: proposal capability descriptor is malformed');
   439	  }
   440	  return key;
   441	}
