   424	/**
   425	 * STRICT Finding schema (sweep hardening). `.strict()` REJECTS unknown keys — the
   426	 * host-A findings file is untrusted caller-supplied input, so an extra/contradictory
   427	 * key (or a missing required field, or a wrong-typed field) must FAIL CLOSED, not be
   428	 * silently dropped. Mirrors the frozen `Finding` shape (adversarial-review.ts).
   429	 */
   430	const hostAFindingSchema = z.object({
   431	  severity: z.enum(FINDING_SEVERITIES),
   432	  title: z.string(),
   433	  file: z.string(),
   434	  line: z.number(),
   435	  issue: z.string(),
   436	  fix: z.string(),
   437	}).strict();
