   442	/**
   443	 * Parse + STRICTLY validate the host-A (Claude) findings from a JSON file. Must be a
   444	 * JSON array of `Finding` with EXACTLY the frozen fields — no missing, no extra, no
   445	 * wrong-typed keys. Any deviation fails closed with a descriptive error (host A is
   446	 * caller-authored, untrusted input; we neither silently drop its findings nor trust
   447	 * `JSON.parse` output that merely happens to carry the required fields).
   448	 *
   449	 * Sweep hardening: replaces the earlier hand-rolled per-field checks (which accepted
   450	 * and silently dropped EXTRA keys) with a strict Zod array — closing the same
   451	 * unknown-key trust-boundary gap fixed for the codex verdict schema.
   452	 */
   453	function loadHostAFindings(path: string): Finding[] {
   454	  let raw: string;
   455	  try {
   456	    raw = readFileSync(path, 'utf8');
   457	  } catch (err) {
   458	    throw new Error(`cross_host_review: cannot read hostAFindingsFile "${path}": ${err instanceof Error ? err.message : String(err)}`);
   459	  }
   460	  let parsed: unknown;
   461	  try {
   462	    parsed = JSON.parse(raw);
   463	  } catch (err) {
   464	    throw new Error(`cross_host_review: hostAFindingsFile "${path}" is not valid JSON: ${err instanceof Error ? err.message : String(err)}`);
   465	  }
   466	  if (!Array.isArray(parsed)) {
   467	    throw new Error(`cross_host_review: hostAFindingsFile "${path}" must contain a JSON array of Finding objects`);
   468	  }
   469	  const result = hostAFindingsSchema.safeParse(parsed);
   470	  if (!result.success) {
   470	  if (!result.success) {
   471	    const issue = result.error.issues[0];
   472	    const where = issue && issue.path.length > 0 ? ` at ${issue.path.join('.')}` : '';
   473	    throw new Error(
   474	      `cross_host_review: hostAFindingsFile "${path}" is not a strict array of Finding objects`
   475	      + `${where}: ${issue ? issue.message : 'invalid'} `
   476	      + `(each entry must have EXACTLY severity/title/file/line/issue/fix — no missing, extra, or wrong-typed keys)`,
   477	    );
   478	  }
   479	  return result.data;
   480	}
