   555	      `cross_host_review: dispatch policy "${check.policy}" is not authorized (${check.status}); `
   556	      + `refusing to spawn the codex review subprocess. reasons: ${check.reasons.join('; ') || '(none)'}`,
   557	    );
   558	  }
   559	  const authorized = check.normalizedPolicy;
   560	  const grantsReviewOnlyCodex = authorized.allowReviewOnlyRealHostSubprocess === true
   561	    && (authorized.allowedHosts ?? []).includes('codex');
   562	  if (!grantsReviewOnlyCodex) {
